import { ref, type Ref } from 'vue';

/**
 * Generic composable that manages a confirmation dialog state.
 * It stores a payload of type `T`, controls dialog visibility,
 * and provides methods to open, cancel, and confirm the dialog.
 * @template T - Type of the payload handled by the confirmation dialog
 * @returns Object containing dialog state, payload, and open/cancel/confirm handlers
 */
export function useConfirmDialog<T>(): {
  cancel: () => void
  confirm: () => T | null
  isOpen: Ref<boolean>
  open: (payload: T) => void
  payload: Ref<T | null>
} {
  const isOpen = ref(false);
  const payload = ref<T | null>(null) as Ref<T | null>;

  /**
   * Opens the confirmation dialog with a given payload.
   * @param value - Data to associate with the confirmation action
   */
  function open(value: T): void {
    payload.value = value;
    isOpen.value = true;
  }

  /**
   * Cancels the confirmation dialog and clears the payload.
   */
  function cancel(): void {
    payload.value = null;
    isOpen.value = false;
  }

  /**
   * Confirms the action and returns the stored payload.
   * Also resets the dialog state.
   * @returns The confirmed payload or null if none exists
   */
  function confirm(): T | null {
    const value = payload.value;
    payload.value = null;
    isOpen.value = false;
    return value;
  }

  return {
    cancel,
    confirm,
    isOpen,
    open,
    payload,
  };
}

import { computed, ref, type ComputedRef } from 'vue';

/**
 * Simple composable that manages a boolean panel state (open/close/toggle).
 *
 * Useful for dialogs, side panels, drawers, and modals.
 * @param initial - Initial open state of the panel (default: false)
 * @returns Object containing reactive panel state and control methods
 */
export function usePanel(initial = false): {
  close: () => void
  isOpen: ComputedRef<boolean>
  open: () => void
  setOpen: (value: boolean) => void
  toggle: () => void
} {
  const openReference = ref(initial);

  /**
   * Opens the panel.
   */
  function open(): void {
    openReference.value = true;
  }

  /**
   * Closes the panel.
   */
  function close(): void {
    openReference.value = false;
  }

  /**
   * Toggles the panel state between open and closed.
   */
  function toggle(): void {
    openReference.value = !openReference.value;
  }

  /**
   * Sets the panel state explicitly.
   * @param value - True to open the panel, false to close it
   */
  function setOpen(value: boolean): void {
    openReference.value = value;
  }

  const isOpen = computed(() => openReference.value);

  return {
    close,
    isOpen,
    open,
    setOpen,
    toggle,
  };
}

