interface ApiArrayEnvelope<T> {
  data?: Array<T>
  limit?: number
  offset?: number
  total?: number
}

interface LocalizedDescription {
  code?: string
  description?: string
}

interface EquipmentClassListItemDto extends Omit<Isa95EquipmentClassDto, 'equipmentLevelId' | 'parentEquipmentClassId'> {
