/**
 * Extracts the most appropriate description for the equipment class.
 * @param equipmentClass Equipment class object to extract description from.
 * @returns The most appropriate description for the equipment class, preferring the main description field, then English localized description, then any available description as a fallback. Returns undefined if no descriptions are available.
 */
function extractEquipmentClassDescription(
  equipmentClass: EquipmentClassListItemDto | Isa95EquipmentClassDto | undefined,
): string | undefined {
  const classWithDescriptions = equipmentClass as EquipmentClassListItemDto | undefined;
  const englishDescription = classWithDescriptions?.descriptions?.find(description => description.code === 'EN')?.description;
  const fallbackDescription = classWithDescriptions?.descriptions?.[0]?.description;

  return equipmentClass?.description ?? englishDescription ?? fallbackDescription;
}

/**
 * Generate authorization headers with bearer token if available.
 * @returns Record containing authorization header, or empty object if no token
 */
function authHeaders(): Record<string, string> {
  if (!token) {
    return {};
  }
  return { authorization: `Bearer ${token}` };
}

/**
 * Normalize array-like API responses that may be returned directly or wrapped in a paginated envelope.
 * @param payload - Raw API payload
 * @returns Normalized array data
 */
function extractArrayData<T>(payload: Array<T> | ApiArrayEnvelope<T> | undefined): Array<T> {
  if (Array.isArray(payload)) {
    return payload;
  }

  if (payload !== undefined && Array.isArray(payload.data)) {
    return payload.data;
  }

  return [];
}

interface ApiClient {
  get<T>(url: string, config?: unknown): Promise<AxiosResponse<T>>
  post<T>(url: string, payload?: unknown, config?: unknown): Promise<AxiosResponse<T>>
  patch<T>(url: string, payload?: unknown, config?: unknown): Promise<AxiosResponse<T>>
  delete<T>(url: string, config?: Record<string, unknown>): Promise<AxiosResponse<T>>
}

const axios: ApiClient = {
  get: async (url: string, config?: unknown) =>
    axiosLib.get(url, config as Record<string, unknown>),
  post: async (url: string, payload?: unknown, config?: unknown) =>
    axiosLib.post(url, payload, config as Record<string, unknown>),
  patch: async (url: string, payload?: unknown, config?: unknown) =>
    axiosLib.patch(url, payload, config as Record<string, unknown>),
  delete: async (url: string, config?: Record<string, unknown>) =>
    axiosLib.delete(url, config),
};

/**
 * Fetch the restricted ISA-95 hierarchy descriptions for a given plant code.
 * @param plant - Plant code to filter hierarchy by (e.g. "S001")
 * @returns Array of hierarchy description root nodes
