): Promise<Array<Isa95HierarchyDescriptionNodeDto>> {
  const response: AxiosResponse<Array<Isa95HierarchyDescriptionNodeDto> | ApiArrayEnvelope<Isa95HierarchyDescriptionNodeDto> | undefined> = await axios.get(
    `${hierarchyUrl}/isa95-equipment-model/getHierarchy`,
