/**
 * Fetch equipment classes from the paginated equipment-classe endpoint.
 * @param equipmentLevelId - Optional equipment level filter
 * @returns List of equipment classes
 */
export async function getEquipmentClasses(
  equipmentLevelId?: number,
): Promise<Array<Isa95EquipmentClassDto>> {
  const response: AxiosResponse<ApiArrayEnvelope<EquipmentClassListItemDto> | undefined> = await axios.get(
    `${hierarchyUrl}/isa95-equipment-model/equipment-classes/equipment-classe`,
    {
      headers: authHeaders(),
      params: {
        limit: 50,
        offset: 0,
      },
    },
  );

  const classes: Array<Isa95EquipmentClassDto> = extractArrayData(response.data).map((row): Isa95EquipmentClassDto => {
    return {
      ...row,
      equipmentLevelId: row.equipmentLevelId ?? 0,
      parentEquipmentClassId: row.parentEquipmentClassId ?? null,
      description: extractEquipmentClassDescription(row),
    };
  });

  if (equipmentLevelId === undefined) {
    return classes;
  }

  const filtered = classes.filter(row => row.equipmentLevelId === equipmentLevelId);

  // Some backend responses omit equipmentLevelId; in that case keep API data visible.
  return filtered.length > 0 ? filtered : classes;
}

/**
 * Fetch one equipment class with nested relations including dynamic properties.
 * @param classId - Equipment class identifier
 * @returns Equipment class details with relations
 */
export async function getEquipmentClassWithRelations(
  classId: number,
): Promise<Isa95EquipmentClassDto | undefined> {
  const response: AxiosResponse<EquipmentClassListItemDto | undefined> = await axios.get(
    `${hierarchyUrl}/isa95-equipment-model/equipment-classes/${classId}/with-relations`,
    {
      headers: authHeaders(),
    },
  );

  if (response.data === undefined) {
    return undefined;
  }

  return {
    ...response.data,
    equipmentLevelId: response.data.equipmentLevelId ?? 0,
    parentEquipmentClassId: response.data.parentEquipmentClassId ?? null,
    description: extractEquipmentClassDescription(response.data),
  };
}

