/**
 * Fetch all properties assigned to a specific equipment class.
 * @param classId - Equipment class identifier
 * @returns List of equipment class properties for the given class
 */
export async function getEquipmentClassPropertiesByClass(
  classId: number,
): Promise<Array<Isa95EquipmentClassPropertyDto>> {
  const response: AxiosResponse<
    Array<EquipmentClassPropertyApiDto>
    | ApiArrayEnvelope<EquipmentClassPropertyApiDto>
    | undefined
  > = await axios.get(
    `${hierarchyUrl}/isa95-equipment-model/equipment-class-properties/by-class/${classId}`,
    {
      headers: authHeaders(),
    },
  );

  return extractArrayData(response.data).map(property => ({
    ...property,
    cardinality: property.propertySemanticsJson?.cardinality ?? null,
    classPropertyType: property.propertySemanticsJson?.classPropertyType ?? null,
    defaultValue:
      property.defaultValue
      ?? property.propertySemanticsJson?.defaultValue
      ?? null,
  }));
}

