/**
 * Converts a property name into an uppercase comparison key.
 * @param value Raw property name or displayed code.
 * @returns Uppercase key used for duplicate checks.
 */
function getComparablePropertyCode(value: string | undefined): string {
  const trimmed = value?.trim();
  return trimmed?.toUpperCase() ?? '';
}

export const useEquipmentClassStore = defineStore('isa95EquipmentClass', () => {
  const notify = inject<{
    success: (options: { title?: string, message: string }) => void
    error: (options: { title?: string, message: string }) => void
    warning: (options: { title?: string, message: string }) => void
  }>('notify');

  const classRows = ref<Array<Isa95EquipmentClassDto>>([]);
  const equipmentLevels = ref<Array<Isa95EquipmentLevelDto>>([]);
  const selectedClassRows = ref<Array<EquipmentClassTableRow>>([]);
  const inlineEditingRowId = ref<number | undefined>(undefined);
  const inlineEditForm = ref({
    code: '',
    description: undefined as string | undefined,
    equipmentLevelId: undefined as number | undefined,
  });
  const deleteDialogOpen = ref(false);
  const pendingDeleteClassId = ref<number | undefined>(undefined);
  const pendingDeleteClassCode = ref('');

  const dialogOpen = ref(false);
  const isEditing = ref(false);
  const editingId = ref<number | undefined>(undefined);

  const createdDialogOpen = ref(false);
  const createdCode = ref('');
  const createdId = ref<number | undefined>(undefined);

  const form = ref<EquipmentClassFormState>({
    code: '',
    description: '',
    equipmentLevelId: undefined,
  });
  const submitting = ref(false);

  const classProperties = ref<Array<Isa95EquipmentClassPropertyDto>>([]);
  const propertyDataTypes = ref<Array<Isa95PropertyDataTypeDto>>([]);
  const propertiesViewOpen = ref(false);
  const selectedClass = ref<Isa95EquipmentClassDto | undefined>(undefined);
  const searchQuery = ref('');
  const plantFilter = ref('all');
  const propertyPanelOpen = ref(false);
  const propertyIsEditing = ref(false);
  const propertyEditingId = ref<number | undefined>(undefined);
  const propertyEditAllowed = ref(true);
  const propertyForm = ref<PropertyFormState>({
    allowedValues: undefined,
    cardinality: 'single',
    classPropertyType: 'InstanceType',
    code: '',
    defaultValue: undefined,
    description: undefined,
    equipmentClassId: undefined,
    length: undefined,
    propertyDataTypeId: undefined,
    scale: undefined,
  });
  const relatedPanelOpen = ref(false);
  const propertyDeleteDialogOpen = ref(false);
  const pendingDeletePropertyId = ref<number | undefined>(undefined);
  const propertyInlineEditingRowId = ref<number | undefined>(undefined);
  const propertyInlineEditForm = ref<InlineEditState>({
    defaultValue: undefined,
    description: undefined,
    length: undefined,
    propertyDataTypeId: undefined,
  });

  const levelOptions = computed(() =>
    equipmentLevels.value.map(level => ({
      label: `${level.code} (#${level.id})`,
      value: level.id,
    })),
  );

  /**
   * Loads equipment levels once and reuses them for create/edit dialogs.
   */
  async function ensureEquipmentLevels(): Promise<void> {
    if (equipmentLevels.value.length > 0) {
      return;
    }

    equipmentLevels.value = await getEquipmentLevelsApi();
  }

  const classTableRows = computed<Array<EquipmentClassTableRow>>(() =>
    classRows.value.map(row => ({
      ...row,
      description: row.description ?? '',
      numberOfProperties: row.equipmentClassPropertiesCount ?? 0,
    })),
  );

  /**
   * Loads equipment classes into the store without fetching per-row relations.
   */
  async function load(): Promise<void> {
    try {
      const classes = await getEquipmentClassesApi();

      classRows.value = classes;
    }
    catch (error) {
      classRows.value = [];
      equipmentLevels.value = [];
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to load equipment classes.',
      });
    }
  }

  /**
   * Selects the equipment class row that matches the provided identifier.
   * @param id Equipment class identifier to select.
   */
  function selectById(id: number): void {
    const target = classTableRows.value.find(row => row.id === id);
    selectedClassRows.value = target ? [target] : [];
  }

  /**
   * Opens the create dialog with a reset equipment class form.
   */
  async function openCreate(): Promise<void> {
    await ensureEquipmentLevels();
    isEditing.value = false;
    editingId.value = undefined;
    inlineEditingRowId.value = undefined;
    form.value = {
      code: '',
      description: '',
      equipmentLevelId: levelOptions.value[0]?.value ?? 1,
    };
    dialogOpen.value = true;
  }

  /**
   * Opens the edit dialog and seeds the form with the selected equipment class values.
   * @param row Equipment class row to edit.
   */
  async function openEdit(row: EquipmentClassTableRow): Promise<void> {
    let details: Isa95EquipmentClassDto | undefined;

    try {
      await ensureEquipmentLevels();
      details = await getEquipmentClassWithRelationsApi(row.id);
    }
    catch {
      notify?.warning({ message: 'Unable to refresh class details. Using current row values.' });
    }

    if (details) {
      classRows.value = classRows.value.map(existing =>
        existing.id === row.id
          ? {
              ...existing,
              ...details,
              description: details.description ?? existing.description,
            }
          : existing,
      );
    }

    isEditing.value = true;
    editingId.value = details?.id ?? row.id;
    inlineEditingRowId.value = undefined;
    form.value = {
      code: details?.code ?? row.code,
      description: details?.description ?? row.description ?? '',
      equipmentLevelId: details?.equipmentLevelId ?? row.equipmentLevelId,
    };
    dialogOpen.value = true;
  }

  /**
   * Creates a new equipment class or updates the currently edited one.
   * @returns A promise that resolves with the created record when a new class is created.
   */
  async function submit(): Promise<{ created: Isa95EquipmentClassDto | undefined }> {
    if (submitting.value) {
      return { created: undefined };
    }

    const code = form.value.code.trim();
    const description = form.value.description.trim();
    const levelId = form.value.equipmentLevelId;

    if (code.length === 0 || description.length === 0) {
      notify?.warning({ message: 'Class name and description are required.' });
      return { created: undefined };
    }

    submitting.value = true;
    try {
      if (isEditing.value && editingId.value !== undefined) {
        const updated = await updateEquipmentClassApi(editingId.value, {
          code,
          description,
          descriptionLanguageCode: 'EN',
        });

        if (!updated) {
          notify?.error({ message: 'Failed to save equipment class.' });
          return { created: undefined };
        }

        classRows.value = classRows.value.map(row => (
          row.id === editingId.value
            ? {
                ...row,
                ...updated,
                description,
                equipmentLevelId: updated.equipmentLevelId ?? row.equipmentLevelId,
              }
            : row
        ));

        notify?.success({ message: 'Equipment class updated.' });
        dialogOpen.value = false;
        return { created: undefined };
      }

      const created = await createEquipmentClassApi({
        className: code,
        description,
        descriptionLanguageCode: 'EN',
      });

      if (!created) {
        notify?.error({ message: 'Failed to create equipment class.' });
        return { created: undefined };
      }

      const createdRow: Isa95EquipmentClassDto = {
        ...created,
        description,
        equipmentLevelId: created.equipmentLevelId ?? levelId,
      };

      classRows.value = [...classRows.value, createdRow];

      notify?.success({ message: 'Equipment class created.' });
      dialogOpen.value = false;
      createdCode.value = createdRow.code;
      createdId.value = createdRow.id;
      createdDialogOpen.value = true;
      return { created: createdRow };
    }
    catch (error) {
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to save equipment class.',
      });
      return { created: undefined };
    }
    finally {
      submitting.value = false;
    }
  }

  /**
   * Deletes an equipment class and removes its related local state.
   * @param id Equipment class identifier to delete.
   * @returns A promise that resolves to true when the class is removed successfully.
   */
  async function remove(id: number): Promise<boolean> {
    try {
      await deleteEquipmentClassApi(id);
      classRows.value = classRows.value.filter(row => row.id !== id);

      notify?.success({ message: 'Equipment class deleted.' });
      return true;
    }
    catch (error) {
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to delete equipment class.',
      });
      return false;
    }
  }

  /**
   * Starts inline editing for the provided equipment class row.
   * @param row Equipment class row to edit inline.
   */
  function startInlineEdit(row: EquipmentClassTableRow): void {
    inlineEditingRowId.value = row.id;
    inlineEditForm.value = {
      code: row.code,
      description: row.description,
      equipmentLevelId: row.equipmentLevelId ?? levelOptions.value[0]?.value ?? undefined,
    };
  }

  /**
   * Cancels the active inline edit session for an equipment class.
   */
  function cancelInlineEdit(): void {
    inlineEditingRowId.value = undefined;
  }

  /**
   * Persists inline edits for an equipment class row.
   * @param row Equipment class row being updated.
   * @returns A promise that resolves to true when the update succeeds.
   */
  async function saveInlineEdit(row: EquipmentClassTableRow): Promise<boolean> {
    const code = inlineEditForm.value.code.trim();
    const levelId = inlineEditForm.value.equipmentLevelId;
    const trimmedDescription = inlineEditForm.value.description?.trim();
    const description = trimmedDescription !== undefined && trimmedDescription.length > 0
      ? trimmedDescription
      : undefined;

    if (code.length === 0 || levelId === undefined) {
      notify?.warning({ message: 'Code and equipment level are required.' });
      return false;
    }

    try {
      const updated = await updateEquipmentClassApi(row.id, {
        code,
        description,
        descriptionLanguageCode: 'EN',
      });

      if (!updated) {
        notify?.error({ message: 'Failed to update equipment class.' });
        return false;
      }

      classRows.value = classRows.value.map(r =>
        r.id === row.id
          ? {
              ...r,
              ...updated,
              description: inlineEditForm.value.description?.trim() ?? r.description,
              equipmentLevelId: updated.equipmentLevelId ?? Number(levelId),
            }
          : r,
      );
      notify?.success({ message: 'Equipment class updated.' });
      inlineEditingRowId.value = undefined;
      return true;
    }
    catch (error) {
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to update equipment class.',
      });
      return false;
    }
  }

  /**
   * Opens the delete confirmation dialog for an equipment class row.
   * @param row Equipment class row queued for deletion.
   */
  function requestDelete(row: EquipmentClassTableRow): void {
    pendingDeleteClassId.value = row.id;
    pendingDeleteClassCode.value = row.code;
    deleteDialogOpen.value = true;
  }

  /**
   * Closes the delete confirmation dialog and clears its pending state.
   */
  function cancelDelete(): void {
    deleteDialogOpen.value = false;
    pendingDeleteClassId.value = undefined;
    pendingDeleteClassCode.value = '';
  }

  /**
   * Confirms deletion of the pending equipment class.
   * @returns True when the deletion succeeds, false when nothing was pending.
   */
  async function confirmDelete(): Promise<boolean> {
    const id = pendingDeleteClassId.value;
    if (id === undefined) {
      cancelDelete();
      return false;
    }

    deleteDialogOpen.value = false;
    pendingDeleteClassId.value = undefined;
    pendingDeleteClassCode.value = '';
    return await remove(id);
  }

  /**
   * Closes the post-creation confirmation dialog.
   */
  function closeCreatedDialog(): void {
    createdDialogOpen.value = false;
  }

  /**
   * Loads local property data-type options used by the properties table and panel.
   */
  async function loadProperties(): Promise<void> {
    propertyDataTypes.value = await getPropertyDataTypesApi();
  }

  /**
   * Refreshes the property rows for a specific equipment class from the backend.
   * @param classId Equipment class identifier.
   */
  async function loadPropertiesByClass(classId: number): Promise<void> {
    const properties = await getEquipmentClassPropertiesByClassApi(classId);
    classProperties.value = [
      ...classProperties.value.filter(property => property.equipmentClassId !== classId),
      ...properties,
    ];
  }

  /**
   * Opens the class properties view for the selected equipment class.
   * @param equipmentClass Equipment class whose properties should be displayed.
   */
  async function openPropertiesView(equipmentClass: Isa95EquipmentClassDto): Promise<void> {
    try {
      selectedClass.value = await getEquipmentClassWithRelationsApi(equipmentClass.id) ?? equipmentClass;
    }
    catch {
      selectedClass.value = equipmentClass;
      notify?.warning({ message: 'Unable to refresh class details. Showing current data.' });
    }

    try {
      await loadPropertiesByClass(equipmentClass.id);
    }
    catch (error) {
      classProperties.value = classProperties.value.filter(property => property.equipmentClassId !== equipmentClass.id);
      notify?.warning({
        message: error instanceof Error
          ? error.message
          : 'Unable to load class properties.',
      });
    }

    searchQuery.value = '';
    plantFilter.value = 'all';
    propertyInlineEditingRowId.value = undefined;
    propertiesViewOpen.value = true;
  }

  /**
   * Closes the class properties view and clears related filters.
   */
  function closePropertiesView(): void {
    propertiesViewOpen.value = false;
    relatedPanelOpen.value = false;
    searchQuery.value = '';
    plantFilter.value = 'all';
  }

  /**
   * Opens the property creation panel with a reset property form.
   */
  function openCreateProperty(): void {
    propertyIsEditing.value = false;
    propertyEditingId.value = undefined;
    propertyEditAllowed.value = true;
    propertyForm.value = {
      allowedValues: undefined,
      cardinality: 'single',
      classPropertyType: 'InstanceType',
      code: '',
      defaultValue: undefined,
      description: undefined,
      equipmentClassId: selectedClass.value?.id,
      length: undefined,
      propertyDataTypeId: undefined,
      scale: undefined,
    };
    propertyPanelOpen.value = true;
  }

  /**
   * Opens the property panel in edit mode, seeding the form from the selected property row.
   * @param row Equipment class property row to edit.
   */
  function openEditProperty(row: Isa95EquipmentClassPropertyDto): void {
    if (!row.isCustom) {
      propertyEditAllowed.value = false;
      notify?.warning({ message: 'Only custom properties can be edited.' });
      return;
    }

    propertyIsEditing.value = true;
    propertyEditingId.value = row.id;
    propertyEditAllowed.value = true;
    propertyForm.value = {
      allowedValues: row.allowedValues ?? undefined,
      cardinality: row.cardinality === 'array' ? 'array' : 'single',
      classPropertyType: row.classPropertyType ?? 'InstanceType',
      code: row.code,
      defaultValue: row.defaultValue ?? undefined,
      description: row.description ?? undefined,
      equipmentClassId: row.equipmentClassId,
      length: row.length ?? undefined,
      propertyDataTypeId: row.propertyDataTypeId,
      scale: row.scale ?? undefined,
    };
    propertyPanelOpen.value = true;
  }

  /**
   * Normalizes an optional property description by trimming whitespace.
   * @param description Raw description from the property form.
   * @returns The trimmed description, or undefined when empty.
   */
  function getNormalizedPropertyDescription(
    description: string | undefined,
  ): string | undefined {
    const trimmedDescription = description?.trim();

    return trimmedDescription !== undefined && trimmedDescription.length > 0
      ? trimmedDescription
      : undefined;
  }

  /**
   * Resolves the class property type to a trimmed value or the default type.
   * @param classPropertyType Raw class property type from the form.
   * @returns A valid class property type string.
   */
  function getNormalizedClassPropertyType(
    classPropertyType: string | undefined,
  ): string {
    const trimmedClassPropertyType = classPropertyType?.trim();

    return trimmedClassPropertyType !== undefined
      && trimmedClassPropertyType.length > 0
      ? trimmedClassPropertyType
      : 'InstanceType';
  }

  /**
   * Builds the semantics payload sent with a class property request.
   * @param cardinality Property cardinality.
   * @param classPropertyType Normalized class property type.
   * @param defaultValue Optional default value for the property.
   * @returns Semantics payload for the backend API.
   */
  function buildPropertySemantics(
    cardinality: 'single' | 'array',
    classPropertyType: string,
    defaultValue: string | number | undefined,
  ): Record<string, unknown> {
    return {
      cardinality,
      classPropertyType,
      ...(defaultValue === undefined
        ? {}
        : { defaultValue: String(defaultValue) }),
    };
  }

  /**
   * Returns currently loaded properties for the active class.
   * @returns Combined loaded property rows for the selected/edited class.
   */
  function getCurrentClassProperties(): Array<Isa95EquipmentClassPropertyDto> {
    const classId = Number(
      propertyForm.value.equipmentClassId
      ?? selectedClass.value?.id
      ?? 0,
    );

    if (classId <= 0) {
      return [];
    }

    const loadedProperties = classProperties.value.filter(property => property.equipmentClassId === classId);
    const relationProperties = (selectedClass.value?.equipmentClassProperties ?? []).filter(
      property => property.equipmentClassId === classId,
    );

    return [...loadedProperties, ...relationProperties].filter(
      (property, index, properties) => properties.findIndex(candidate => candidate.id === property.id) === index,
    );
  }

  /**
   * Checks whether the current property name would duplicate an existing class property.
   * @returns True when another property already uses the same displayed name.
   */
  function hasDuplicatePropertyCode(): boolean {
    const currentCode = getComparablePropertyCode(propertyForm.value.code);

    if (currentCode.length === 0) {
      return false;
    }

    return getCurrentClassProperties().some((property) => {
      const isDifferentProperty = propertyEditingId.value === undefined
        ? true
        : property.id !== propertyEditingId.value;

      return isDifferentProperty
        && getComparablePropertyCode(formatDisplayValue(property.code)) === currentCode;
    });
  }

  /**
   * Builds the normalized create/update payload for a class property.
   * @returns API-ready payload derived from the current property form state.
   */
  function buildPropertyPayload() {
    const code = propertyForm.value.code.trim().toUpperCase();

    return {
      code,
      description: getNormalizedPropertyDescription(
        propertyForm.value.description,
      ),
      equipmentClassId: Number(propertyForm.value.equipmentClassId ?? 0),
      length:
        propertyForm.value.length === undefined
          ? undefined
          : Number(propertyForm.value.length),
      propertyDataTypeId: Number(propertyForm.value.propertyDataTypeId ?? 1),
      propertySemanticsJson: buildPropertySemantics(
        propertyForm.value.cardinality ?? 'single',
        getNormalizedClassPropertyType(propertyForm.value.classPropertyType),
        propertyForm.value.defaultValue,
      ),
      scale:
        propertyForm.value.scale === undefined
          ? undefined
          : Number(propertyForm.value.scale),
    };
  }

  /**
   * Reloads properties for the currently selected class when one is active.
   * @returns A promise that resolves after the class property list is refreshed.
   */
  async function refreshSelectedClassProperties(): Promise<void> {
    if (selectedClass.value?.id !== undefined) {
      await loadPropertiesByClass(selectedClass.value.id);
    }
  }

  /**
   * Updates the currently edited class property through the API.
   * @param editId Identifier of the property being updated.
   * @returns A promise that resolves to true when the update succeeds.
   */
  async function updateProperty(editId: number): Promise<boolean> {
    const payload = buildPropertyPayload();
    const updated = await updateEquipmentClassPropertyApi(editId, {
      code: payload.code,
      ...(payload.description === undefined
        ? {}
        : {
            description: payload.description,
            descriptionCode: 'EN',
          }),
      equipmentClassId: payload.equipmentClassId,
      length: payload.length,
      propertyDataTypeId: payload.propertyDataTypeId,
      propertySemanticsJson: payload.propertySemanticsJson,
      scale: payload.scale,
    });

    if (updated === undefined) {
      notify?.error({ message: 'Failed to update property.' });
      return false;
    }

    await refreshSelectedClassProperties();
    notify?.success({ message: 'Property updated.' });
    return true;
  }

  /**
   * Creates a new class property through the API.
   * @returns A promise that resolves to true when the creation succeeds.
   */
  async function createProperty(): Promise<boolean> {
    const payload = buildPropertyPayload();
    const created = await createEquipmentClassPropertyApi({
      code: payload.code,
      ...(payload.description === undefined
        ? {}
        : {
            description: payload.description,
            descriptionCode: 'EN',
          }),
      equipmentClassId: payload.equipmentClassId,
      length: payload.length,
      propertyDataTypeId: payload.propertyDataTypeId,
      propertySemanticsJson: payload.propertySemanticsJson,
      scale: payload.scale,
    });

    if (created === undefined) {
      notify?.error({ message: 'Failed to create property.' });
      return false;
    }

    await refreshSelectedClassProperties();
    notify?.success({ message: 'Property created.' });
    return true;
  }

  /**
   * Creates a new class property or updates the currently edited property.
   * @returns A promise that resolves to true when the property is saved successfully.
   */
  async function submitProperty(): Promise<boolean> {
    if (propertyIsEditing.value && !propertyEditAllowed.value) {
      notify?.warning({ message: 'Only custom properties can be updated.' });
      return false;
    }

    const hasRequired
      = propertyForm.value.code.trim().length > 0
        && propertyForm.value.propertyDataTypeId !== undefined;

    if (!hasRequired) {
      notify?.warning({ message: 'Code and data type are required.' });
      return false;
    }

    if (hasDuplicatePropertyCode()) {
      notify?.error({ message: 'Property name already exists.' });
      return false;
    }

    try {
      const saved = propertyIsEditing.value && propertyEditingId.value !== undefined
        ? await updateProperty(propertyEditingId.value)
        : await createProperty();

      if (!saved) {
        return false;
      }

      propertyPanelOpen.value = false;
      return true;
    }
    catch (error) {
      notify?.error({ message: 'Failed to save property.' });
      console.error('Failed to save property', error);
      return false;
    }
  }

  /**
   * Deletes an equipment class property and refreshes the property list.
   * @param id Equipment class property identifier to delete.
   * @returns A promise that resolves to true when the deletion succeeds.
   */
  async function removeProperty(id: number): Promise<boolean> {
    propertyInlineEditingRowId.value = undefined;
    try {
      await deleteEquipmentClassPropertyApi(id);
      classProperties.value = classProperties.value.filter(p => p.id !== id);
      if (selectedClass.value?.id !== undefined) {
        classRows.value = classRows.value.map(row =>
          row.id === selectedClass.value?.id
            ? {
                ...row,
                equipmentClassPropertiesCount: Math.max(
                  (row.equipmentClassPropertiesCount ?? 0) - 1,
                  0,
                ),
              }
            : row,
        );
      }
      notify?.success({ message: 'Property deleted.' });
      return true;
    }
    catch (error) {
      notify?.error({ message: 'Failed to delete property.' });
      console.error('Failed to delete property', error);
      return false;
    }
  }

  /**
   * Opens the delete confirmation dialog for an equipment class property.
   * @param row Equipment class property identifier queued for deletion.
   */
  function requestPropertyDelete(row: Isa95EquipmentClassPropertyDto): void {
    if (!row.isCustom) {
      notify?.warning({ message: 'Only custom properties can be deleted.' });
      return;
    }

    pendingDeletePropertyId.value = row.id;
    propertyDeleteDialogOpen.value = true;
  }

  /**
   * Closes the property delete confirmation dialog and clears its pending state.
   */
  function cancelPropertyDelete(): void {
    propertyDeleteDialogOpen.value = false;
    pendingDeletePropertyId.value = undefined;
  }

  /**
   * Confirms deletion of the pending equipment class property.
   * @returns True when the property is deleted, otherwise false.
   */
  async function confirmPropertyDelete(): Promise<boolean> {
    const id = pendingDeletePropertyId.value;
    if (id === undefined) {
      cancelPropertyDelete();
      return false;
    }

    propertyDeleteDialogOpen.value = false;
    pendingDeletePropertyId.value = undefined;
    return await removeProperty(id);
  }

  /**
   * Starts inline editing for the provided equipment class property row.
   * @param row Equipment class property row to edit inline.
   */
  function startPropertyInlineEdit(row: Isa95EquipmentClassPropertyDto): void {
    propertyInlineEditingRowId.value = row.id;
    propertyInlineEditForm.value = {
      defaultValue: row.defaultValue ?? undefined,
      description: row.description ?? undefined,
      length: row.length ?? undefined,
      propertyDataTypeId: row.propertyDataTypeId,
    };
  }

  /**
   * Cancels the active inline edit session for a class property.
   */
  function cancelPropertyInlineEdit(): void {
    propertyInlineEditingRowId.value = undefined;
  }

  /**
   * Persists inline edits for an equipment class property row.
   * @param row Equipment class property row being updated.
   */
  function savePropertyInlineEdit(row: Isa95EquipmentClassPropertyDto): void {
    try {
      classProperties.value = classProperties.value.map(p =>
        p.id === row.id
          ? {
              ...p,
              defaultValue: propertyInlineEditForm.value.defaultValue ?? null,
              description: propertyInlineEditForm.value.description ?? null,
              length: propertyInlineEditForm.value.length ?? null,
              propertyDataTypeId: propertyInlineEditForm.value.propertyDataTypeId ?? p.propertyDataTypeId,
            }
          : p,
      );
      notify?.success({ message: 'Property updated.' });
      propertyInlineEditingRowId.value = undefined;
    }
    catch (error) {
      notify?.error({ message: 'Failed to update property.' });
      console.error('Failed to update property', error);
    }
  }

  /**
   * Builds the filtered property rows for the currently selected class.
   * @param equipmentClassLinks Equipment-to-class relationship rows used for site filtering.
   * @param equipmentRows Equipment rows used to resolve the active plant filter.
   * @returns A computed list of properties matching the selected class and active filters.
   */
  function filteredPropertyRows(
    equipmentClassLinks: Ref<Array<Isa95EquipmentEquipmentClassDto>>,
    equipmentRows: Ref<Array<Isa95EquipmentDto>>,
  ): ComputedRef<Array<Isa95EquipmentClassPropertyDto>> {
    return computed(() => {
      const classId = selectedClass.value?.id;
      if (classId === undefined) return [];

      let rows = getRowsByClassId(classId);

      rows = applySearchFilter(rows);

      if (plantFilter.value === 'all') return rows;

      return applyPlantFilter(rows, equipmentClassLinks, equipmentRows);
    });
  }

  /**
   * Filters all properties belonging to a specific equipment class.
   * @param classId The ID of the selected equipment class.
   * @returns A list of properties associated with the given class ID.
   */
  function getRowsByClassId(
    classId: number,
  ): Array<Isa95EquipmentClassPropertyDto> {
    return classProperties.value.filter(
      property => property.equipmentClassId === classId,
    );
  }

  /**
   * Applies a text-based search filter to the provided property rows.
   * @param rows The list of property rows to filter.
   * @returns A filtered list of properties matching the search query.
   */
  function applySearchFilter(
    rows: Array<Isa95EquipmentClassPropertyDto>,
  ): Array<Isa95EquipmentClassPropertyDto> {
    const normalized = searchQuery.value.trim().toLowerCase();
    if (normalized.length === 0) return rows;

    return rows.filter(property => matchesSearch(property, normalized));
  }

  /**
   * Determines whether a property matches the given search query.
   * @param property The property to evaluate.
   * @param normalized The normalized (lowercase, trimmed) search string.
   * @returns True if the property matches the search query; otherwise false.
   */
  function matchesSearch(
    property: Isa95EquipmentClassPropertyDto,
    normalized: string,
  ): boolean {
    const dtype
      = propertyDataTypes.value.find(
        dt => dt.id === property.propertyDataTypeId,
      )?.code ?? '';

    return [property.code, property.defaultValue ?? '', dtype]
      .join(' ')
      .toLowerCase()
      .includes(normalized);
  }

  /**
   * Applies plant/site-based filtering to property rows.
   * @param rows The list of property rows to filter.
   * @param equipmentClassLinks Equipment-to-class relationship rows.
   * @param equipmentRows Equipment rows used to resolve site filtering.
   * @returns A filtered list of properties associated with the selected plant.
   */
  function applyPlantFilter(
    rows: Array<Isa95EquipmentClassPropertyDto>,
    equipmentClassLinks: Ref<Array<Isa95EquipmentEquipmentClassDto>>,
    equipmentRows: Ref<Array<Isa95EquipmentDto>>,
  ): Array<Isa95EquipmentClassPropertyDto> {
    const siteEquipmentIds = getSiteEquipmentIds(equipmentRows);
    const linkedClassIds = getLinkedClassIds(equipmentClassLinks, siteEquipmentIds);

    return rows.filter(property =>
      linkedClassIds.has(property.equipmentClassId),
    );
  }

  /**
   * Retrieves the set of equipment IDs belonging to the selected plant.
   * @param equipmentRows All available equipment rows.
   * @returns A set of equipment IDs filtered by the active plant.
   */
  function getSiteEquipmentIds(
    equipmentRows: Ref<Array<Isa95EquipmentDto>>,
  ): Set<number> {
    return new Set(
      equipmentRows.value
        .filter(equipment => equipment.site === plantFilter.value)
        .map(equipment => equipment.id),
    );
  }

  /**
   * Retrieves the set of equipment class IDs linked to the provided equipment IDs.
   * @param equipmentClassLinks Equipment-to-class relationship rows.
   * @param siteEquipmentIds Set of equipment IDs filtered by plant.
   * @returns A set of equipment class IDs associated with the given equipment IDs.
   */
  function getLinkedClassIds(
    equipmentClassLinks: Ref<Array<Isa95EquipmentEquipmentClassDto>>,
    siteEquipmentIds: Set<number>,
  ): Set<number> {
    return new Set(
      equipmentClassLinks.value
        .filter(link => siteEquipmentIds.has(link.equipmentId))
        .map(link => link.equipmentClassId),
    );
  }

  return {
    cancelDelete,
    cancelInlineEdit,
    classRows,
    classTableRows,
    closeCreatedDialog,
    confirmDelete,
    createdCode,
    createdDialogOpen,
    createdId,
    deleteDialogOpen,
    dialogOpen,
    editingId,
    form,
    inlineEditForm,
    inlineEditingRowId,
    isEditing,
    levelOptions,
    load,
    openCreate,
    openEdit,
    pendingDeleteClassCode,
    remove,
    requestDelete,
    saveInlineEdit,
    selectById,
    selectedClassRows,
    startInlineEdit,
    submit,
    submitting,

    cancelPropertyDelete,
    cancelPropertyInlineEdit,
    classProperties,
    closePropertiesView,
    confirmPropertyDelete,
    filteredPropertyRows,
    loadProperties,
    openCreateProperty,
    openEditProperty,
    openPropertiesView,
    pendingDeletePropertyId,
    plantFilter,
    propertiesViewOpen,
    propertyDataTypes,
    propertyDeleteDialogOpen,
    propertyForm,
    propertyInlineEditForm,
    propertyInlineEditingRowId,
    propertyIsEditing,
    propertyEditAllowed,
    propertyPanelOpen,
    relatedPanelOpen,
    requestPropertyDelete,
    savePropertyInlineEdit,
    searchQuery,
    selectedClass,
    startPropertyInlineEdit,
    submitProperty,
  } satisfies EquipmentClassStoreState & Record<string, unknown>;
});

