} from '../services/api';
import type { EquipmentFormState } from '../types';
import type { Isa95HierarchyFlatRowDto } from '../types/isa95-hierarchy-flat-row-dto';

export interface EquipmentClassLinkPayload {
  equipmentId: number
  equipmentClassId: number
  site: number
}

interface NotifyService {
  success: (options: { title?: string, message: string }) => void
  error: (options: { title?: string, message: string }) => void
  warning: (options: { title?: string, message: string }) => void
}

export interface EquipmentStoreState {
  createEquipmentLevels: Ref<Array<Isa95EquipmentLevelDto>>
  createOptionsLoading: Ref<boolean>
  createParentOptions: Ref<Array<Isa95ParentEquipmentOptionDto>>
  createPropertiesByClassId: Ref<Record<number, Array<Isa95EquipmentClassPropertyDto>>>
  createRelatedClasses: Ref<Array<Isa95EquipmentClassDto>>
  dialogOpen: Ref<boolean>
  editingId: Ref<number | undefined>
  equipmentRows: Ref<Array<Isa95EquipmentDto>>
  flatRows: Ref<Array<Isa95HierarchyFlatRowDto>>
  flatRowsError: Ref<string | null>
  flatRowsLoading: Ref<boolean>
  form: Ref<EquipmentFormState>
  isEditing: Ref<boolean>
  links: Ref<Array<Isa95EquipmentEquipmentClassDto>>
  loading: Ref<boolean>
  properties: Ref<Array<Isa95EquipmentPropertyDto>>
}

export const useEquipmentStore = defineStore('isa95Equipment', () => {
  const notify = inject<NotifyService>('notify');

  // ── Real API state ────────────────────────────────────────────────────────
  const flatRows = ref<Array<Isa95HierarchyFlatRowDto>>([]);
  const flatRowsLoading = ref(false);
  const flatRowsError = ref<string | null>(null);
  const createOptionsLoading = ref(false);
  const createEquipmentLevels = ref<Array<Isa95EquipmentLevelDto>>([]);
  const createParentOptions = ref<Array<Isa95ParentEquipmentOptionDto>>([]);
  const createRelatedClasses = ref<Array<Isa95EquipmentClassDto>>([]);
  const createPropertiesByClassId = ref<Record<number, Array<Isa95EquipmentClassPropertyDto>>>({});

  /**
   * Loads equipment details along with its related entities for a given equipment ID.
   * @param id - Unique identifier of the equipment to load.
   * @returns
   * A promise that resolves to the equipment DTO with relations if successful,
   * or `undefined` if the loading fails.
   * @remarks
   * In case of an error during the loading process, an error notification is displayed
   * and the function safely returns `undefined` instead of throwing.
   */
  async function loadEquipmentWithRelations(
    id: number,
  ): Promise<Isa95EquipmentDto | undefined> {
    try {
      return await getEquipmentWithRelations(id);
    }
    catch {
      notify?.error({ message: 'Failed to load equipment details.' });
      return undefined;
    }
  }

  /**
   * Save equipment details (general info, class links, and properties) in one call.
   * @param id - Equipment ID to save
   * @param payload - SaveEquipmentDetailsDto with fields to update, classes, and properties
   * @returns Updated equipment with all relations if successful, or undefined on error
   */
  async function saveEquipmentDetails(
    id: number,
    payload: SaveEquipmentDetailsDto,
  ): Promise<Isa95EquipmentDto | undefined> {
    try {
      const updated = await saveEquipmentDetailsApi(id, payload);
      if (updated) {
        notify?.success({ message: 'Equipment details saved successfully.' });
      }
      else {
        notify?.error({ message: 'Failed to save equipment details.' });
      }
      return updated;
    }
    catch (error) {
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to save equipment details.',
      });
      return undefined;
    }
  }

  // ── In-memory CRUD state ──────────────────────────────────────────────────
  const equipmentRows = ref<Array<Isa95EquipmentDto>>([]);
  const links = ref<Array<Isa95EquipmentEquipmentClassDto>>([]);
  const properties = ref<Array<Isa95EquipmentPropertyDto>>([]);
  const loading = ref(false);

  const dialogOpen = ref(false);
  const isEditing = ref(false);
  const editingId = ref<number | undefined>(undefined);

  const form = ref<EquipmentFormState>({
    code: '',
    description: '',
    equipmentLevelId: undefined,
    erpSource: '',
    parentEquipmentId: undefined,
    sapObjId: 1,
    site: '',
  });

  // ── Helpers ───────────────────────────────────────────────────────────────

  /**
   * @returns Next available numeric ID for equipment.
   */
  function nextEquipmentId(): number {
    return Math.max(0, ...equipmentRows.value.map(r => r.id)) + 1;
  }

  /**
   * @returns Next available numeric ID for equipment-class links.
   */
  function nextLinkId(): number {
    return Math.max(0, ...links.value.map(l => l.id)) + 1;
  }

  /**
   * @returns Next available numeric ID for equipment properties.
   */
  function nextPropertyId(): number {
    return Math.max(0, ...properties.value.map(p => p.id)) + 1;
  }

  // ── Real API actions ──────────────────────────────────────────────────────

  /**
   * Loads the flat equipment table from the backend using the current user's plant.
   * Each equipment may appear in multiple rows when joined with multiple classes or properties.
   */
  async function loadEquipment(): Promise<void> {
    const profileStore = useProfileStore();
    const plant = String(profileStore.userAttributes.plant);

    flatRowsLoading.value = true;
    flatRowsError.value = null;

    try {
      flatRows.value = await getHierarchyDetailsFlat(plant);
    }
    catch (error) {
      flatRowsError.value = error instanceof Error ? error.message : String(error);
      flatRows.value = [];
      notify?.error({ message: 'Failed to load equipment data.' });
    }
    finally {
      flatRowsLoading.value = false;
    }
  }

  /**
   * Loads equipment level options for the create panel.
   */
  async function loadCreateEquipmentLevels(): Promise<void> {
    createOptionsLoading.value = true;
    try {
      createEquipmentLevels.value = await getEquipmentLevelsApi();
    }
    catch {
      createEquipmentLevels.value = [];
      notify?.error({ message: 'Failed to load equipment levels.' });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /**
   * Loads valid parent candidates for a given equipment level in the current plant.
   * @param equipmentLevelId - Selected equipment level identifier.
   */
  async function loadCreateParentOptions(equipmentLevelId: number): Promise<void> {
    if (equipmentLevelId <= 0) {
      createParentOptions.value = [];
      return;
    }

    createOptionsLoading.value = true;
    try {
      const profileStore = useProfileStore();
      const parsedPlant = Number.parseInt(String(profileStore.userAttributes.plant), 10);
      const plant = Number.isNaN(parsedPlant) ? 0 : parsedPlant;

      createParentOptions.value = await getParentEquipmentOptionsApi(
        plant,
        equipmentLevelId,
      );
    }
    catch {
      createParentOptions.value = [];
      notify?.error({ message: 'Failed to load parent options.' });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /**
   * Loads equipment classes filtered by the selected equipment level.
   * @param equipmentLevelId - Selected equipment level identifier.
   */
  async function loadCreateRelatedClasses(equipmentLevelId?: number): Promise<void> {
    createOptionsLoading.value = true;
    try {
      createRelatedClasses.value = await getEquipmentClassesApi(equipmentLevelId);
    }
    catch {
      createRelatedClasses.value = [];
      notify?.error({ message: 'Failed to load related classes.' });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /**
   * Loads dynamic property definitions for each selected equipment class.
   * @param classIds - Selected equipment class identifiers.
   */
  async function loadCreateClassProperties(classIds: Array<number>): Promise<void> {
    if (classIds.length === 0) {
      createPropertiesByClassId.value = {};
      return;
    }

    createOptionsLoading.value = true;
    try {
      const classDetails = await Promise.all(
        classIds.map(async classId => ({
          classId,
          details: await getEquipmentClassWithRelations(classId),
        })),
      );

      createPropertiesByClassId.value = classDetails.reduce<Record<number, Array<Isa95EquipmentClassPropertyDto>>>(
        (accumulator, entry) => {
          accumulator[entry.classId] = entry.details?.equipmentClassProperties ?? [];
          return accumulator;
        },
        {},
      );
    }
    catch {
      createPropertiesByClassId.value = {};
      notify?.error({ message: 'Failed to load class properties.' });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /**
   * Initializes create panel metadata using the provided level or the first available level.
   * @param defaultEquipmentLevelId - Optional initial equipment level identifier.
   */
  async function initializeCreatePanel(defaultEquipmentLevelId?: number): Promise<void> {
    await loadCreateEquipmentLevels();

    const fallbackLevelId = createEquipmentLevels.value[0]?.id ?? 0;
    const selectedLevelId = defaultEquipmentLevelId ?? fallbackLevelId;
    if (selectedLevelId <= 0) {
      createParentOptions.value = [];
      createRelatedClasses.value = [];
      createPropertiesByClassId.value = {};
      return;
    }

    await Promise.all([
      loadCreateParentOptions(selectedLevelId),
      loadCreateRelatedClasses(selectedLevelId),
    ]);
  }

  /**
   * Creates equipment with related classes and dynamic properties in one request.
   * @param payload - Create payload from the equipment create panel.
   * @returns Created equipment with relations when successful, otherwise undefined.
   */
  async function createEquipmentWithDetails(
    payload: CreateEquipmentWithDetailsDto,
  ): Promise<Isa95EquipmentDto | undefined> {
    const description = (payload.description ?? '').trim();
    const generatedCode = description.length > 0
      ? description.split(/\s+/).join('_')
      : 'NEW_EQUIPMENT';

    const profileStore = useProfileStore();
    const parsedPlant = Number.parseInt(String(profileStore.userAttributes.plant), 10);
    const fallbackPlant = Number.isNaN(parsedPlant) ? 0 : parsedPlant;
    const trimmedCode = payload.code?.trim();
    const resolvedCode = trimmedCode !== undefined && trimmedCode.length > 0
      ? trimmedCode
      : generatedCode;

    const requestPayload: CreateEquipmentWithDetailsDto = {
      ...payload,
      code: resolvedCode,
      description,
      erpSource: payload.erpSource ?? '',
      plant: payload.plant ?? fallbackPlant,
      sapObjId: payload.sapObjId ?? 1,
    };

    // Validate: code must equal plant only for SITE level (equipmentLevelId === 1)
    const isSiteLevel = payload.equipmentLevelId === 1;
    if (isSiteLevel && requestPayload.code !== String(requestPayload.plant)) {
      notify?.warning({ message: 'For Site level, equipment code must be exactly equal to plant.' });
      return undefined;
    }

    try {
      const created = await createEquipmentWithDetailsApi(requestPayload);
      if (created) {
        notify?.success({ message: 'Equipment created successfully.' });
      }
      else {
        notify?.error({ message: 'Failed to create equipment.' });
      }
      return created;
    }
    catch {
      notify?.error({ message: 'Failed to create equipment.' });
      return undefined;
    }
  }

  /**
   * Initialises the equipment properties collection.
   */
  function loadProperties(): void {
    properties.value = [];
  }

  /**
   * Opens the equipment creation dialog and initializes the form.
   * @param defaults - Optional partial form values to pre-fill the dialog.
   */
  function openCreate(defaults?: Partial<EquipmentFormState>): void {
    isEditing.value = false;
    editingId.value = undefined;
    form.value = {
      code: '',
      description: '',
      equipmentLevelId: defaults?.equipmentLevelId ?? undefined,
      erpSource: '',
      parentEquipmentId: defaults?.parentEquipmentId ?? undefined,
      sapObjId: 1,
      site: defaults?.site ?? '',
    };
    dialogOpen.value = true;
  }

  /**
   * Opens the equipment edit dialog and maps the selected row into the form state.
   * @param row - Equipment row to populate into the edit form.
   */
  function openEdit(row: Isa95EquipmentDto): void {
    isEditing.value = true;
    editingId.value = row.id;
    form.value = {
      code: row.code,
      description: row.description,
      equipmentLevelId: row.equipmentLevelId,
      erpSource: row.erpSource,
      parentEquipmentId: row.parentEquipmentId ?? undefined,
      sapObjId: row.sapObjId,
      site: row.site,
    };
    dialogOpen.value = true;
  }

  /**
   * Validates the current form and creates or updates the equipment record in-memory.
   * @returns True when the save succeeds, false otherwise.
   */
  function submit(): boolean {
    const requiredFieldsValid
      = form.value.site.length > 0
        && form.value.code.length > 0
        && form.value.equipmentLevelId !== undefined;

    if (!requiredFieldsValid) {
      notify?.warning({ message: 'Site, Code and Level are required.' });
      return false;
    }

    const payload: CreateEquipmentPayload = {
      code: form.value.code.trim(),
      description: form.value.description.trim(),
      equipmentLevelId: Number(form.value.equipmentLevelId),
      erpSource: form.value.erpSource.trim(),
      sapObjId: Number(form.value.sapObjId),
      site: form.value.site.trim(),
    };

    if (form.value.parentEquipmentId !== undefined) {
      payload.parentEquipmentId = Number(form.value.parentEquipmentId);
    }

    try {
      if (isEditing.value && editingId.value !== undefined) {
        const id = editingId.value;
        equipmentRows.value = equipmentRows.value.map(r =>
          r.id === id ? { ...r, ...payload } : r,
        );
        notify?.success({ message: 'Equipment updated.' });
      }
      else {
        const created: Isa95EquipmentDto = {
          id: nextEquipmentId(),
          site: payload.site,
          code: payload.code,
          description: payload.description,
          sapObjId: payload.sapObjId,
          equipmentLevelId: payload.equipmentLevelId,
          parentEquipmentId: payload.parentEquipmentId ?? null,
          erpSource: payload.erpSource,
        };
        equipmentRows.value = [...equipmentRows.value, created];
        notify?.success({ message: 'Equipment created.' });
      }
      dialogOpen.value = false;
      return true;
    }
    catch {
      notify?.error({ message: 'Failed to save equipment.' });
      return false;
    }
  }

  /**
   * Removes an equipment record and its related links and properties.
   * @param id - ID of the equipment record to delete.
   * @returns True when deletion succeeds, false otherwise.
   */
  async function remove(id: number): Promise<boolean> {
    try {
      await deleteEquipmentApi(id);
      equipmentRows.value = equipmentRows.value.filter(r => r.id !== id);
      flatRows.value = flatRows.value.filter(row => row.id !== id);
      links.value = links.value.filter(l => l.equipmentId !== id);
      properties.value = properties.value.filter(p => p.equipmentId !== id);
      notify?.success({ message: 'Equipment deleted.' });
      return true;
    }
    catch {
      notify?.error({ message: 'Failed to delete equipment.' });
      return false;
    }
  }

  /**
   * Creates a link between an equipment record and an equipment class if it does not already exist.
   * @param payload - Identifiers required to create the class link.
   */
  function addEquipmentClassLink(payload: EquipmentClassLinkPayload): void {
    const alreadyLinked = links.value.some(
      l =>
        l.equipmentId === payload.equipmentId
        && l.equipmentClassId === payload.equipmentClassId,
    );

    if (!alreadyLinked) {
      links.value = [
        ...links.value,
        {
          id: nextLinkId(),
          equipmentId: payload.equipmentId,
          equipmentClassId: payload.equipmentClassId,
          site: payload.site,
        },
      ];
    }
  }

  /**
   * Removes the link between an equipment record and an equipment class.
   * @param payload - Identifiers required to delete the class link.
   */
  function removeEquipmentClassLink(payload: EquipmentClassLinkPayload): void {
    links.value = links.value.filter(
      l =>
        !(
          l.equipmentId === payload.equipmentId
          && l.equipmentClassId === payload.equipmentClassId
        ),
    );
  }

  /**
   * Links an equipment record to an equipment class.
   * @param payload - Identifiers required to create the class link.
   */
  function linkEquipmentClass(payload: EquipmentClassLinkPayload): void {
    addEquipmentClassLink(payload);
  }

  /**
   * Unlinks an equipment record from an equipment class.
   * @param payload - Identifiers required to delete the class link.
   */
  function unlinkEquipmentClass(payload: EquipmentClassLinkPayload): void {
    removeEquipmentClassLink(payload);
  }

  /**
   * Persists property values for an equipment record (merges if record already exists).
   * @param equipmentId - ID of the equipment whose properties are being saved.
   * @param site - Site associated with the property record.
   * @param propertiesJson - Serialized property values keyed by property code.
   */
  function savePropertyValues(
    equipmentId: number,
    site: string,
    propertiesJson: Record<string, unknown>,
  ): void {
    const existing = properties.value.find(p => p.equipmentId === equipmentId);
    if (existing) {
      existing.propertiesJson = { ...existing.propertiesJson, ...propertiesJson };
    }
    else {
      properties.value = [
        ...properties.value,
        {
          id: nextPropertyId(),
          equipmentId,
          equipmentClassId: equipmentId,
          site,
          propertiesJson,
        },
      ];
    }
  }

  /**
   * Replaces all equipment-class links for a given class with a new set of equipment IDs.
   * @param equipmentClassId - The class whose links are being replaced.
   * @param equipmentIds - New set of equipment IDs to link.
   */
  function updateRelatedEquipments(equipmentClassId: number, equipmentIds: Array<number>): void {
    const otherLinks = links.value.filter(l => l.equipmentClassId !== equipmentClassId);
    const newLinks = equipmentIds.map((equipmentId, index) => ({
      id: nextLinkId() + index,
      equipmentId,
      equipmentClassId,
      site: 1,
    }));
    links.value = [...otherLinks, ...newLinks];
  }

  return {
    dialogOpen,
    editingId,
    equipmentRows,
    flatRows,
    flatRowsError,
    flatRowsLoading,
    createEquipmentLevels,
    createOptionsLoading,
    createParentOptions,
    createPropertiesByClassId,
    createRelatedClasses,
    form,
    isEditing,
    links,
    loading,
    loadEquipment,
    loadEquipmentWithRelations,
    createEquipmentWithDetails,
    initializeCreatePanel,
    loadCreateClassProperties,
    loadCreateEquipmentLevels,
    loadCreateParentOptions,
    loadCreateRelatedClasses,
    saveEquipmentDetails,
    loadProperties,
    openCreate,
    openEdit,
    properties,
    remove,
    savePropertyValues,
    submit,
    linkEquipmentClass,
    unlinkEquipmentClass,
    updateRelatedEquipments,
  } satisfies EquipmentStoreState & {
    loadEquipment: () => Promise<void>
    loadEquipmentWithRelations: (id: number) => Promise<Isa95EquipmentDto | undefined>
    createEquipmentWithDetails: (payload: CreateEquipmentWithDetailsDto) => Promise<Isa95EquipmentDto | undefined>
    initializeCreatePanel: (defaultEquipmentLevelId?: number) => Promise<void>
    loadCreateClassProperties: (classIds: Array<number>) => Promise<void>
    loadCreateEquipmentLevels: () => Promise<void>
    loadCreateParentOptions: (equipmentLevelId: number) => Promise<void>
    loadCreateRelatedClasses: (equipmentLevelId?: number) => Promise<void>
    saveEquipmentDetails: (id: number, payload: SaveEquipmentDetailsDto) => Promise<Isa95EquipmentDto | undefined>
    loadProperties: () => void
    openCreate: (defaults?: Partial<EquipmentFormState>) => void
    openEdit: (row: Isa95EquipmentDto) => void
    remove: (id: number) => Promise<boolean>
    savePropertyValues: (equipmentId: number, site: string, propertiesJson: Record<string, unknown>) => void
    submit: () => boolean
    linkEquipmentClass: (payload: EquipmentClassLinkPayload) => void
    unlinkEquipmentClass: (payload: EquipmentClassLinkPayload) => void
    updateRelatedEquipments: (equipmentClassId: number, equipmentIds: Array<number>) => void
  };
});

import { defineStore } from 'pinia';
import { computed, ref } from 'vue';
import { useProfileStore } from '../../../Auth/store/user-auth-store';
import { getRestrictedHierarchyDescriptions } from '../services/api';
import type { Isa95HierarchyDescriptionNodeDto } from '../types/isa95-hierarchy-description-node-dto';
import type { TreeNode } from '../types/tree-node';

const LEVEL_ICONS: Record<string, string> = {
  site: 'factory',
  area: 'corporate_fare',
  line: 'view_stream',
  wc: 'lan',
  res: 'memory',
  cell: 'grid_view',
};

/**
 * Resolve icon name by ISA-95 level code.
 * @param levelCode - The ISA-95 level code
 * @returns The Material Symbol icon name for the given level
 */
function getNodeIcon(levelCode: string): string {
  return LEVEL_ICONS[levelCode.toLowerCase()] ?? 'device_hub';
}

/**
 * Filter tree nodes recursively while preserving matching ancestors.
 * @param nodes - Array of tree nodes to filter
 * @param query - Search query string
 * @returns Filtered array of tree nodes that match the query
 */
function filterTree(nodes: Array<TreeNode>, query: string): Array<TreeNode> {
  const normalized = query.trim().toLowerCase();
  if (normalized.length === 0) return nodes;

  return nodes
    .map((node) => {
      const children = filterTree(node.children, normalized);
      const match = [node.code, node.description, node.levelCode]
        .join(' ')
        .toLowerCase()
        .includes(normalized);

      return match || children.length > 0 ? { ...node, children } : undefined;
    })
    .filter((entry): entry is TreeNode => entry !== undefined);
}

/**
 * Count all nodes in the tree recursively.
 * @param nodes - Array of tree nodes to count
 * @returns Total count of all nodes including descendants
 */
function flattenCount(nodes: Array<TreeNode>): number {
  let count = 0;

  const visit = (items: Array<TreeNode>) => {
    for (const item of items) {
      count += 1;
      if (item.children.length > 0) visit(item.children);
    }
  };

  visit(nodes);
  return count;
}

/**
 * Get all node IDs that belong to the active branch (expanded nodes and all their ancestors).
 * @param nodes - Array of tree nodes
 * @param expanded - Array of currently expanded node IDs
 * @returns Set of active branch node IDs
 */
function getActiveBranchNodes(nodes: Array<TreeNode>, expanded: Array<string>): Set<string> {
  const activeBranch = new Set<string>();

  const visit = (items: Array<TreeNode>, ancestors: Array<string> = []): void => {
    for (const item of items) {
      if (expanded.includes(item.id)) {
        for (const ancestor of ancestors) {
          activeBranch.add(ancestor);
        }
        activeBranch.add(item.id);
      }
      if (item.children.length > 0) {
        visit(item.children, [...ancestors, item.id]);
      }
    }
  };

  visit(nodes);
  return activeBranch;
}

/**
 * Map an array of description DTOs to TreeNodes under a given level code.
 * @param nodes - Array of hierarchy description DTOs
 * @param levelCode - The ISA-95 level code to assign to the mapped nodes
 * @returns Array of mapped TreeNode objects
 */
function mapChildren(
  nodes: Array<Isa95HierarchyDescriptionNodeDto>,
  levelCode: string,
): Array<TreeNode> {
  return nodes.map(node => mapNodeToTreeNode(node, levelCode));
}

/**
 * Map a single hierarchy description DTO to a TreeNode.
 * @param node - Hierarchy description DTO from the backend
 * @param levelCode - The ISA-95 level code to assign to this node
 * @returns A TreeNode ready for use in the q-tree component
 */
function mapNodeToTreeNode(
  node: Isa95HierarchyDescriptionNodeDto,
  levelCode: string,
): TreeNode {
  const children: Array<TreeNode> = [
    ...mapChildren(node.area ?? [], 'area'),
    ...mapChildren(node.productionLine ?? [], 'line'),
    ...mapChildren(node.workCenter ?? [], 'wc'),
    ...mapChildren(node.workUnit ?? [], 'res'),
  ];

  return {
    id: node.code,
    code: node.code,
    label: node.displayLabel,
    description: node.description,
    levelCode,
    children,
  };
}

/**
 * Collect node IDs to auto-expand up to a given depth.
 * @param nodes - Array of tree nodes
 * @param depth - Current recursion depth
 * @param maxDepth - Maximum depth to expand
 * @returns Array of node IDs that should be expanded
 */
function collectExpandedIds(nodes: Array<TreeNode>, depth: number, maxDepth: number): Array<string> {
  if (depth >= maxDepth) return [];
  const ids: Array<string> = [];
  for (const node of nodes) {
    if (node.children.length > 0) {
      ids.push(node.id, ...collectExpandedIds(node.children, depth + 1, maxDepth));
    }
  }
  return ids;
}

/**
 * Collect node IDs that should be expanded to reveal matching search results.
 * Expands any node that matches the query or has matching descendants.
 * @param nodes - Array of tree nodes
 * @param query - Search query string
 * @param expanded - Set to accumulate expanded node IDs
 * @returns true if this node or any descendant matches
 */
function collectSearchExpandedIds(
  nodes: Array<TreeNode>,
  query: string,
  expanded = new Set<string>(),
): Set<string> {
  const normalized = query.trim().toLowerCase();
  if (normalized.length === 0) return expanded;

  const collect = (items: Array<TreeNode>): boolean => {
    let hasMatch = false;
    for (const node of items) {
      const nodeMatches = [node.code, node.description, node.levelCode]
        .join(' ')
        .toLowerCase()
        .includes(normalized);

      const childrenHaveMatches = node.children.length > 0 && collect(node.children);

      if (nodeMatches || childrenHaveMatches) {
        expanded.add(node.id);
        hasMatch = true;
      }
    }
    return hasMatch;
  };

  collect(nodes);
  return expanded;
}

export const useHierarchyStore = defineStore('isa95Hierarchy', () => {
  const hierarchy = ref<Array<TreeNode>>([]);
  const searchQuery = ref('');
  const expanded = ref<Array<string>>([]);
  const selectedNodeId = ref<string | undefined>(undefined);
  const isLoading = ref(false);
  const loadError = ref<string | null>(null);
  const selectedNodeForFilter = ref<TreeNode | null>(null);

  const visibleTree = computed(() => filterTree(hierarchy.value, searchQuery.value));
  const hierarchyCount = computed(() => flattenCount(visibleTree.value));
  const activeBranch = computed(() => getActiveBranchNodes(hierarchy.value, expanded.value));

  /**
   *
   */
  async function loadHierarchy(): Promise<void> {
    const userAttributesStore = useProfileStore();
    const plant = String(userAttributesStore.userAttributes.plant);

    isLoading.value = true;
    loadError.value = null;

    try {
      const nodes = await getRestrictedHierarchyDescriptions(plant);
      hierarchy.value = nodes.map(node => mapNodeToTreeNode(node, 'site'));
      expanded.value = collectExpandedIds(hierarchy.value, 0, Infinity);
    }
    catch (error) {
      loadError.value = error instanceof Error ? error.message : String(error);
      hierarchy.value = [];
    }
    finally {
      isLoading.value = false;
    }
  }

  /**
   * Get all node IDs in the hierarchy.
   * @returns Array of all node IDs
   */
  function getAllHierarchyNodeIds(): Array<string> {
    return collectExpandedIds(hierarchy.value, 0, Infinity);
  }

  /**
   * Get node IDs that should be expanded to reveal search results.
   * @param query - Search query string
   * @returns Array of node IDs to expand
   */
  function getSearchExpandedIds(query: string): Array<string> {
    return [...collectSearchExpandedIds(hierarchy.value, query)];
  }

  /**
   * Set the selected node for equipment filtering.
   * @param node - The tree node to use as a filter
   */
  function setSelectedNodeForFilter(node: TreeNode): void {
    selectedNodeForFilter.value = node;
  }

  /**
   * Clear the selected node filter.
   */
  function clearSelectedNodeForFilter(): void {
    selectedNodeForFilter.value = null;
  }

  return {
    activeBranch,
    clearSelectedNodeForFilter,
    expanded,
    getAllHierarchyNodeIds,
    getNodeIcon,
    getSearchExpandedIds,
    hierarchy,
    hierarchyCount,
    isLoading,
    loadError,
    loadHierarchy,
    searchQuery,
    selectedNodeForFilter,
    selectedNodeId,
    setSelectedNodeForFilter,
    visibleTree,
  };
});

